import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { spawnSync } from 'node:child_process';
import { createManifest, verifyManifest } from '../snapshot.js';

const script = fileURLToPath(new URL('../snapshot.js', import.meta.url));
function fixture(t) {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'snapshot-extra-'));
  t.after(() => fs.rmSync(root, {recursive:true, force:true}));
  return root;
}
function write(root, name, bytes = 'abc') {
  fs.mkdirSync(path.dirname(path.join(root, name)), {recursive:true});
  fs.writeFileSync(path.join(root, name), bytes);
  fs.chmodSync(path.join(root, name), 0o640);
}
function cli(...args) {
  return spawnSync(process.execPath, [script, ...args], {encoding:'utf8'});
}

test('classifies each path once and preserves frozen unsorted input', t => {
  const root = fixture(t);
  const names = ['unchanged', 'size', 'mode', 'both', 'content', 'gone/file', 'link/file', 'blocked/file', 'directory'];
  for (const name of names) write(root, name);
  const built = createManifest(root, Object.freeze(names));
  const manifest = Object.freeze({version:1, files:Object.freeze(built.files.reverse().map(entry =>
    Object.freeze(entry.path === 'size' ? {...entry, size:99} : entry)))});
  fs.chmodSync(path.join(root, 'mode'), 0o600);
  fs.chmodSync(path.join(root, 'both'), 0o600);
  write(root, 'content', 'xyz');
  fs.writeFileSync(path.join(root, 'both'), 'xyz');
  fs.rmSync(path.join(root, 'gone'), {recursive:true});
  fs.rmSync(path.join(root, 'link'), {recursive:true});
  fs.symlinkSync(root, path.join(root, 'link'));
  fs.rmSync(path.join(root, 'blocked'), {recursive:true});
  write(root, 'blocked');
  fs.unlinkSync(path.join(root, 'directory'));
  fs.mkdirSync(path.join(root, 'directory'));
  write(root, 'unselected');
  assert.deepEqual(verifyManifest(root, manifest), {
    ok:false, unchanged:['unchanged'],
    changed:[{path:'both', reasons:['content', 'mode']}, {path:'content', reasons:['content']},
      {path:'mode', reasons:['mode']}, {path:'size', reasons:['content']}],
    missing:['gone/file'], unsafe:['blocked/file', 'directory', 'link/file'],
  });
});

test('validates all manifest fields and canonical paths', t => {
  const root = fixture(t);
  write(root, 'file');
  const entry = createManifest(root, ['file']).files[0];
  const invalidPaths = ['', '/file', 'a\\b', 'a\0b', 'a//b', './a', 'a/../b', 'a/'];
  for (const selected of invalidPaths) {
    assert.throws(() => createManifest(root, [selected]), Error);
    assert.throws(() => verifyManifest(root, {version:1, files:[{...entry, path:selected}]}), Error);
  }
  for (const manifest of [null, [], {}, {version:2, files:[]}, {version:1, files:{}},
    {version:1, files:[null]}, {version:1, files:[[]]}, {version:1, files:[entry, entry]}]) {
    assert.throws(() => verifyManifest(root, manifest), Error);
  }
  for (const patch of [{sha256:entry.sha256.toUpperCase()}, {sha256:entry.sha256 + '\n'},
    {sha256:3}, {size:-1}, {size:1.5}, {size:Number.MAX_SAFE_INTEGER + 1},
    {mode:-1}, {mode:512}, {mode:1.5}, {mode:'420'}]) {
    assert.throws(() => verifyManifest(root, {version:1, files:[entry, {...entry, path:'other', ...patch}]}), Error);
  }
  assert.equal(verifyManifest(root, {version:1, extra:true, files:[{...entry, extra:true}]}).ok, true);
});

test('handles binary bytes, unusual names, empty selections and unsafe roots', t => {
  const root = fixture(t);
  const names = ['é', 'Z', 'a', 'line\nbreak', 'tab\tname', 'with space'];
  for (const name of names) write(root, name, Buffer.from([0, 255, 10]));
  const manifest = createManifest(root, names);
  assert.deepEqual(manifest.files.map(entry => entry.path), [...names].sort());
  assert.deepEqual(verifyManifest(root, manifest).unchanged, [...names].sort());
  assert.deepEqual(createManifest(root, []), {version:1, files:[]});
  assert.equal(verifyManifest(root, {version:1, files:[]}).ok, true);
  fs.symlinkSync(root, path.join(root, 'alias'));
  fs.symlinkSync('absent', path.join(root, 'dangling'));
  const entry = {...manifest.files[0], path:'dangling'};
  assert.deepEqual(verifyManifest(root, {version:1, files:[entry]}).unsafe, ['dangling']);
  for (const badRoot of ['', path.join(root, 'absent'), path.join(root, 'a'), path.join(root, 'alias'), path.join(root, 'alias') + '/']) {
    assert.throws(() => createManifest(badRoot, []), Error);
    assert.throws(() => verifyManifest(badRoot, {version:1, files:[]}), Error);
  }
});

test('CLI emits one JSON line, uses status 0/1/2, and import is silent', t => {
  const root = fixture(t);
  write(root, 'file');
  const created = cli('create', root, 'file');
  assert.equal(created.status, 0);
  assert.equal(created.stderr, '');
  assert.equal(created.stdout, JSON.stringify(createManifest(root, ['file'])) + '\n');
  const manifestFile = path.join(root, 'manifest.json');
  fs.writeFileSync(manifestFile, created.stdout);
  const clean = cli('verify', root, manifestFile);
  assert.equal(clean.status, 0);
  assert.equal(clean.stderr, '');
  assert.equal(JSON.parse(clean.stdout).ok, true);
  write(root, 'file', 'changed');
  const drift = cli('verify', root, manifestFile);
  assert.equal(drift.status, 1);
  assert.equal(drift.stderr, '');
  assert.equal(drift.stdout, JSON.stringify(verifyManifest(root, JSON.parse(created.stdout))) + '\n');
  fs.writeFileSync(manifestFile, '{');
  for (const args of [[], ['nope'], ['create'], ['create', root, '../x'], ['verify', root],
    ['verify', root, manifestFile, 'extra'], ['verify', root, manifestFile], ['verify', root, 'absent']]) {
    const result = cli(...args);
    assert.equal(result.status, 2);
    assert.equal(result.stdout, '');
    assert.ok(result.stderr.trim());
  }
  const imported = spawnSync(process.execPath, ['--input-type=module', '-e',
    `import ${JSON.stringify(new URL('../snapshot.js', import.meta.url).href)}`], {encoding:'utf8'});
  assert.equal(imported.status, 0);
  assert.equal(imported.stdout, '');
  assert.equal(imported.stderr, '');
});

